def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (g[r-1][c] == g[r+1][c] == g[r][c-1] == g[r][c+1] == 2
                    and g[r][c] == 0):
                centers.append((r, c))
    for i, (r1, c1) in enumerate(centers):
        for r2, c2 in centers[i+1:]:
            if r1 == r2 and c1 != c2:
                a, b = sorted((c1, c2))
                for c in range(a + 2, b - 1):
                    if g[r1][c] == 0:
                        g[r1][c] = 1
            elif c1 == c2 and r1 != r2:
                a, b = sorted((r1, r2))
                for r in range(a + 2, b - 1):
                    if g[r][c1] == 0:
                        g[r][c1] = 1
    return g
